import java.net.URI;
import java.net.URL;

public class UriVsUrlDemo {
    public static void main(String[] args) throws Exception {
        // A URI that is a URL
        String urlString = "https://api.example.com:8443/v1/users?active=true#profile";

        URI uri = new URI(urlString);
        URL url = uri.toURL(); // Safe conversion when scheme and authority are present

        System.out.println("Scheme: " + uri.getScheme());
        System.out.println("Host: " + uri.getHost());
        System.out.println("Port: " + uri.getPort());
        System.out.println("Path: " + uri.getPath());
        System.out.println("Query: " + uri.getQuery());

        // Example of a URI that is NOT a URL (URN)
        URI urn = new URI("urn:isbn:978-0134685991");
        System.out.println("URN Scheme: " + urn.getScheme());
        System.out.println("URN Scheme-Specific Part: " + urn.getSchemeSpecificPart());

        // Attempting urn.toURL() would throw a MalformedURLException because a URN has no network locator
    }
}
